'use strict';
const $=id=>document.getElementById(id);
let state=null, poll=null, approvalSignature='';
async function api(path,body){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok){let info=await response.json().catch(()=>({}));throw new Error(typeof info.detail==='string'?info.detail:'Anfrage fehlgeschlagen ('+response.status+').');}return response.json();}
function notice(message){$('notice').textContent=message;}
function safe(fn){return async event=>{event?.preventDefault();try{notice('');await fn(event);}catch(error){notice(error.message);}};}
function panel(name){for(const el of document.querySelectorAll('.panel'))el.hidden=el.id!==name;for(const el of document.querySelectorAll('nav button'))el.classList.toggle('selected',el.dataset.panel===name);const titles={cockpit:'Alles im Blick, Captain.',workshop:'Raum für deine Ideen.',news:'Die Welt im Überblick.',connections:'Verbunden. Unter deiner Kontrolle.',settings:'Dein COMPUTER.'};$('page-title').textContent=titles[name];if(name==='workshop')safe(loadDocs)();}
function element(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function button(text,fn,cls){const el=element('button',text,cls);el.addEventListener('click',safe(fn));return el;}
async function refresh(){state=await api('state');$('login').hidden=true;$('workspace').hidden=false;$('connection').textContent='Sitzung verbunden';$('provider-label').textContent={demo:'Offline-Demo',local:'Lokales Modell',openai:'OpenAI API'}[state.provider.kind];$('model-label').textContent=state.provider.model||'Echter SDK-Runner · simuliertes Modell';$('browser-state').textContent=state.browser.message;$('voice-state').textContent={not_connected:'Bereit für deinen Auftrag.',sleep:'Ruhemodus · Computer hört auf das Wake Word.',listening:'Ich höre zu.',recording:'Aufnahme läuft.',stt:'Sprache wird erkannt.',agent:'Ich bearbeite deinen Auftrag.',tts:'Antwort wird gesprochen.',playback:'COMPUTER spricht.',error:'Audio benötigt Aufmerksamkeit.'}[state.voice.status]||state.voice.status;$('voice-description').textContent=state.voice.error||'Audio auf Zielhardware nicht VALIDATED';$('run-count').textContent=state.runs.filter(r=>!['completed','error','cancelled'].includes(r.status)).length+' aktive Aufträge';renderApprovals();renderRuns();}
function renderApprovals(){const signature=JSON.stringify(state.pending.map(p=>p.id));if(signature===approvalSignature)return;approvalSignature=signature;$('approvals').replaceChildren();for(const p of state.pending){const box=element('article',undefined,'card approval');box.append(element('span',p.risk+' / FREIGABE ERFORDERLICH','eyebrow'),element('h2',p.tool),element('pre',JSON.stringify(p.arguments,null,2)),element('p','Aktion '+p.id+' · maximal 120 Sekunden gültig'));const label=element('label','Exakt eingeben: '+p.phrase),input=element('input');input.autocomplete='off';label.append(input);box.append(label);const controls=element('div',undefined,'quick');controls.append(button('Freigeben',async()=>{await api('approval/'+p.id,{digest:p.digest,phrase:input.value,approve:true});await refresh();},'primary'),button('Ablehnen',async()=>{await api('approval/'+p.id,{digest:p.digest,phrase:'',approve:false});await refresh();}));box.append(controls);$('approvals').append(box);}}
function renderRuns(){const container=$('runs');container.replaceChildren();if(!state.runs.length){container.append(element('p','Dein nächster Auftrag beginnt hier.','muted'));return;}for(const r of [...state.runs].reverse().slice(0,8)){const box=element('article',undefined,'run');box.append(element('small',r.status.toUpperCase()+' · '+r.id.slice(0,8)));let display=r.error||r.output||'COMPUTER arbeitet …';try{const result=JSON.parse(r.output);display=result.message+'\n'+JSON.stringify(result.data,null,2);if(result.data?.items)renderNews(result.data.items);}catch{}box.append(element('p',display));if(!['completed','error','cancelled'].includes(r.status)){const controls=element('div',undefined,'quick');for(const [action,label] of [['pause','Pause anfordern'],['resume','Fortsetzen'],['stop','Stoppen']])controls.append(button(label,async()=>{await api('run/'+r.id+'/'+action,{});await refresh();}));box.append(controls);}container.append(box);}}
function renderNews(items){$('news-items').replaceChildren();for(const item of items){const p=element('p');let url;try{url=new URL(item.url);}catch{continue;}if(url.protocol!=='https:')continue;const link=element('a',item.title);link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';p.append(link,element('small',' '+item.date));$('news-items').append(p);}}
async function send(text){await api('message',{text});panel('cockpit');await refresh();}
async function tool(name,args){await api('tool',{tool:name,arguments:args});await refresh();}
async function loadDocs(){const docs=await api('documents');$('documents').replaceChildren();if(!docs.length)$('documents').append(element('p','Noch keine Entwürfe.'));for(const doc of docs){const row=element('article',undefined,'run'),link=element('a',doc.title+' · '+doc.format.toUpperCase());link.href='/api/documents/'+doc.id;link.download='';row.append(link,element('p',doc.characters+' Zeichen · Integrität geprüft'));row.append(button('Revision erstellen',async()=>{const old=prompt('Welchen Text ersetzen?');if(!old)return;const replacement=prompt('Neuer Text:');if(replacement===null)return;await tool('revise_document',{document_id:doc.id,old,new:replacement});await new Promise(resolve=>setTimeout(resolve,400));await loadDocs();}));$('documents').append(row);}}
$('login-form').addEventListener('submit',safe(async()=>{await api('login',{token:$('token').value});$('token').value='';await refresh();if(!poll)poll=setInterval(()=>refresh().catch(error=>{notice(error.message);clearInterval(poll);poll=null;}),1000);}));
$('chat-form').addEventListener('submit',safe(async()=>{const text=$('message').value;$('message').value='';await send(text);}));
$('draft-form').addEventListener('submit',safe(async()=>{await tool('create_document',{title:$('draft-title').value,text:$('draft-text').value,format:$('draft-format').value});notice('Entwurf beauftragt.');setTimeout(()=>safe(loadDocs)(),500);}));
$('provider-form').addEventListener('submit',safe(async()=>{await api('provider',{kind:$('provider-kind').value,model:$('provider-model').value,temperature:Number($('temperature').value)});await refresh();}));
$('memory-form').addEventListener('submit',safe(async()=>{await api('memory',{response_length:$('response-length').value,address:$('address').value});notice('Sitzungsvorlieben gespeichert.');}));
$('stop').addEventListener('click',safe(async()=>{if(!state)return;for(const r of state.runs.filter(r=>!['completed','error','cancelled'].includes(r.status)))await api('run/'+r.id+'/stop',{});await api('voice/stop',{}).catch(()=>{});await refresh();}));
$('pair-bridge').addEventListener('click',safe(async()=>{$('bridge-code').textContent=(await api('bridge/pair',{})).token;}));
$('drive-list').addEventListener('click',safe(async()=>{await tool('drive_list',{});panel('cockpit');}));
$('refresh-documents').addEventListener('click',safe(loadDocs));
$('logout').addEventListener('click',safe(async()=>{await api('logout',{});location.reload();}));
for(const el of document.querySelectorAll('[data-panel]'))el.addEventListener('click',()=>panel(el.dataset.panel));
for(const el of document.querySelectorAll('[data-command]'))el.addEventListener('click',safe(()=>send(el.dataset.command)));
for(const el of document.querySelectorAll('[data-region]'))el.addEventListener('click',safe(()=>tool('news',{region:el.dataset.region})));
document.addEventListener('keydown',event=>{if(event.key==='Escape')$('stop').click();});
refresh().then(()=>{poll=setInterval(()=>refresh().catch(()=>{}),1000);}).catch(()=>{});
